-- Resolve each manifest to exactly one series and lock it.
create temporary table pd_region_series on commit drop as
select t.manifest_id, s.id as series_id
from pd_region_targets t
join public.series s on s.effect_settings->'publicDomain'->>'manifestId' = t.manifest_id;

select s.id from public.series s
where s.effect_settings->'publicDomain'->>'manifestId' in ('aozora-000234', 'aozora-000235', 'aozora-000237', 'aozora-000249', 'aozora-000380', 'aozora-000452', 'aozora-000545', 'aozora-000669', 'aozora-000869', 'aozora-000874', 'aozora-000875', 'aozora-000903', 'aozora-000907', 'aozora-001321', 'aozora-001334', 'aozora-001341', 'aozora-001663', 'aozora-001783', 'aozora-001786', 'aozora-001814', 'aozora-001816', 'aozora-001950', 'aozora-001951', 'aozora-001952', 'aozora-002225', 'aozora-003033', 'aozora-003406', 'aozora-003411', 'aozora-003585', 'aozora-003829', 'aozora-004332', 'aozora-004398', 'aozora-004680', 'aozora-004798', 'aozora-004799', 'aozora-004801', 'aozora-004910', 'aozora-004960', 'aozora-004961', 'aozora-033227', 'aozora-042289', 'aozora-042290', 'aozora-042389', 'aozora-042390', 'aozora-042391', 'aozora-042614', 'aozora-042615', 'aozora-042616', 'aozora-042756', 'aozora-043418', 'aozora-043422', 'aozora-043552', 'aozora-043553', 'aozora-043606', 'aozora-043646')
for update;

do $$ begin
  if (select count(*) from pd_region_series) <> 55
     or (select count(distinct manifest_id) from pd_region_series) <> 55
     or (select count(distinct series_id) from pd_region_series) <> 55 then
    raise exception 'PD_REGION_ISSUE139_CL_20261115_SERIES_RESOLVE_MISMATCH';
  end if;
  if exists (
    select 1
    from pd_region_targets t
    join pd_region_series m using (manifest_id)
    join public.series s on s.id = m.series_id
    where s.publication_status <> 'private'
       or s.is_public is distinct from false
       or s.content_rating <> 'general'
       or s.title <> t.expected_title
       or not (s.content_warnings @> t.expected_warnings and s.content_warnings <@ t.expected_warnings)
       or s.effect_settings->'publicDomain'->>'rightsChecked' is distinct from 'true'
       or s.effect_settings->'publicDomain'->>'sourceProvider' is distinct from t.source_provider
  ) then raise exception 'PD_REGION_ISSUE139_CL_20261115_SERIES_STATE_DRIFT'; end if;
  if (select count(distinct s.author_id) from pd_region_series m
      join public.series s on s.id = m.series_id) <> 1 then
    raise exception 'PD_REGION_ISSUE139_CL_20261115_AUTHOR_DRIFT';
  end if;
  -- An existing row must already be exactly the reviewed list.
  if exists (
    select 1 from pd_region_targets t
    join pd_region_series m using (manifest_id)
    join public.series_region_restrictions r on r.series_id = m.series_id
    where not (
      (t.mode = 'allow' and r.blocked_countries is null
        and r.allowed_countries @> t.countries and r.allowed_countries <@ t.countries)
   or (t.mode = 'block' and r.allowed_countries is null
        and r.blocked_countries @> t.countries and r.blocked_countries <@ t.countries)
    )
  ) then raise exception 'PD_REGION_ISSUE139_CL_20261115_EXISTING_RESTRICTION_DIFFERS'; end if;
end $$;

create schema if not exists libread_internal;
create table libread_internal.pd_region_issue139_cl_20261115_series (
  series_id uuid primary key,
  manifest_id text not null unique,
  expected_episodes integer not null,
  is_public_before boolean,
  publication_status_before text not null,
  restriction_inserted boolean not null
);
create table libread_internal.pd_region_issue139_cl_20261115_episodes (
  episode_id uuid primary key,
  series_id uuid not null,
  episode_number integer not null,
  is_published_before boolean not null,
  posting_status_before text not null,
  scheduled_for_before timestamptz,
  posted_at_before timestamptz,
  last_edited_at_before timestamptz,
  posted_at_after timestamptz
);
alter table libread_internal.pd_region_issue139_cl_20261115_series enable row level security;
alter table libread_internal.pd_region_issue139_cl_20261115_episodes enable row level security;
revoke all on libread_internal.pd_region_issue139_cl_20261115_series from public, anon, authenticated;
revoke all on libread_internal.pd_region_issue139_cl_20261115_episodes from public, anon, authenticated;

insert into libread_internal.pd_region_issue139_cl_20261115_series
  (series_id, manifest_id, expected_episodes, is_public_before, publication_status_before, restriction_inserted)
select m.series_id, t.manifest_id, t.expected_episodes, s.is_public, s.publication_status,
       not exists (select 1 from public.series_region_restrictions r where r.series_id = m.series_id)
from pd_region_targets t
join pd_region_series m using (manifest_id)
join public.series s on s.id = m.series_id;

insert into libread_internal.pd_region_issue139_cl_20261115_episodes
  (episode_id, series_id, episode_number, is_published_before, posting_status_before,
   scheduled_for_before, posted_at_before, last_edited_at_before)
select e.id, e.series_id, e.episode_number, e.is_published, e.posting_status,
       e.scheduled_for, e.posted_at, e.last_edited_at
from public.episodes e
join libread_internal.pd_region_issue139_cl_20261115_series t on t.series_id = e.series_id;

do $$ begin
  if (select count(*) from libread_internal.pd_region_issue139_cl_20261115_series) <> 55 then
    raise exception 'PD_REGION_ISSUE139_CL_20261115_SERIES_COUNT_MISMATCH';
  end if;
  if (select count(*) from libread_internal.pd_region_issue139_cl_20261115_episodes) <> 277 then
    raise exception 'PD_REGION_ISSUE139_CL_20261115_EPISODE_COUNT_MISMATCH';
  end if;
  if exists (
    select 1 from libread_internal.pd_region_issue139_cl_20261115_episodes
    where posting_status_before <> 'draft' or is_published_before
       or scheduled_for_before is not null or posted_at_before is not null
  ) then raise exception 'PD_REGION_ISSUE139_CL_20261115_EPISODE_STATE_DRIFT'; end if;
  if exists (
    select 1
    from libread_internal.pd_region_issue139_cl_20261115_series t
    left join libread_internal.pd_region_issue139_cl_20261115_episodes e on e.series_id = t.series_id
    group by t.series_id, t.expected_episodes
    having count(e.episode_id) <> t.expected_episodes
        or min(e.episode_number) <> 1
        or max(e.episode_number) <> t.expected_episodes
  ) then raise exception 'PD_REGION_ISSUE139_CL_20261115_EPISODE_NUMBERING_DRIFT'; end if;
end $$;

-- 1) Restriction rows first (same transaction).
insert into public.series_region_restrictions(series_id, blocked_countries, allowed_countries, reason)
select m.series_id,
       case when t.mode = 'block' then t.countries end,
       case when t.mode = 'allow' then t.countries end,
       t.reason
from pd_region_targets t
join pd_region_series m using (manifest_id)
where not exists (
  select 1 from public.series_region_restrictions r where r.series_id = m.series_id
);

do $$ begin
  if (select count(*) from pd_region_targets t
      join pd_region_series m using (manifest_id)
      join public.series_region_restrictions r on r.series_id = m.series_id
      where (
      (t.mode = 'allow' and r.blocked_countries is null
        and r.allowed_countries @> t.countries and r.allowed_countries <@ t.countries)
   or (t.mode = 'block' and r.allowed_countries is null
        and r.blocked_countries @> t.countries and r.blocked_countries <@ t.countries)
    )) <> 55 then
    raise exception 'PD_REGION_ISSUE139_CL_20261115_RESTRICTION_MISSING';
  end if;
end $$;

do $$ begin
  if exists (
    select 1 from libread_internal.pd_region_issue139_cl_20261115_series t
    join public.series_region_restrictions r on r.series_id = t.series_id
    where r.decided_at > now() - interval '120 seconds'
  ) then raise exception 'PD_REGION_ISSUE139_CL_20261115_RESTRICTION_TOO_RECENT'; end if;
end $$;

-- 2) Publish. Only works that now have the reviewed restriction row.
do $$
declare
  v_series integer;
  v_episodes integer;
begin
  update public.series s
    set publication_status = 'public', is_public = true
  from libread_internal.pd_region_issue139_cl_20261115_series t
  where s.id = t.series_id
    and s.publication_status = 'private' and s.is_public = false
    and exists (select 1 from public.series_region_restrictions r where r.series_id = s.id);
  get diagnostics v_series = row_count;
  if v_series <> 55 then
    raise exception 'PD_REGION_ISSUE139_CL_20261115_SERIES_ROWCOUNT_MISMATCH %', v_series;
  end if;

  update public.episodes e
    set posting_status = 'posted', is_published = true, posted_at = now()
  from libread_internal.pd_region_issue139_cl_20261115_episodes t
  where e.id = t.episode_id
    and e.posting_status = 'draft' and e.is_published = false and e.posted_at is null;
  get diagnostics v_episodes = row_count;
  if v_episodes <> 277 then
    raise exception 'PD_REGION_ISSUE139_CL_20261115_EPISODE_ROWCOUNT_MISMATCH %', v_episodes;
  end if;

  update libread_internal.pd_region_issue139_cl_20261115_episodes t
    set posted_at_after = e.posted_at
  from public.episodes e
  where e.id = t.episode_id;

  if (select count(*) from public.public_episode_work_summaries v
      join libread_internal.pd_region_issue139_cl_20261115_series t on t.series_id = v.series_id
      where v.episode_count = t.expected_episodes) <> 55 then
    raise exception 'PD_REGION_ISSUE139_CL_20261115_PUBLIC_VIEW_MISMATCH';
  end if;
  -- No target may be public without its restriction row.
  if exists (
    select 1 from libread_internal.pd_region_issue139_cl_20261115_series t
    join public.series s on s.id = t.series_id
    left join public.series_region_restrictions r on r.series_id = t.series_id
    where s.publication_status = 'public' and r.series_id is null
  ) then raise exception 'PD_REGION_ISSUE139_CL_20261115_PUBLIC_WITHOUT_RESTRICTION'; end if;
end $$;
commit;

